  "passageMeta": {
    "p_07dc0b7f": {
      "texts": {
        "bsb": "Trust in the LORD with all your heart, and lean not on your own understanding; in all your ways acknowledge Him, and He will make your paths straight.",
        "kjv": "¶ Trust in the LORD with all thine heart; and lean not unto thine own understanding. In all thy ways acknowledge him, and he shall direct thy paths."
      },
      "topics": {
        "christian": "Trust in the Lord"
      }
    },
    "p_651440f1": {
      "texts": {
        "bsb": "No temptation has seized you except what is common to man. And God is faithful; He will not let you be tempted beyond what you can bear. But when you are tempted, He will also provide an escape, so that you can stand up under it.",
        "kjv": "There hath no temptation taken you but such as is common to man: but God is faithful, who will not suffer you to be tempted above that ye are able; but will with the temptation also make a way to escape, that ye may be able to bear it."
      },
      "topics": {
        "christian": "A Way Through Temptation"
      }
    },
    "p_c772188b": {
      "texts": {
        "bsb": "All Scripture is God-breathed and is useful for instruction, for conviction, for correction, and for training in righteousness, so that the man of God may be complete, fully equipped for every good work.",
        "kjv": "All scripture is given by inspiration of God, and is profitable for doctrine, for reproof, for correction, for instruction in righteousness: That the man of God may be perfect, throughly furnished unto all good works."
      },
      "topics": {
        "christian": "God-Breathed Scripture"
      }
    },
    "p_8846dfea": {
      "texts": {
        "bsb": "Come to Me, all you who are weary and burdened, and I will give you rest. Take My yoke upon you and learn from Me, for I am gentle and humble in heart, and you will find rest for your souls. For My yoke is easy and My burden is light.”",
        "kjv": "¶ Come unto me, all ye that labour and are heavy laden, and I will give you rest. Take my yoke upon you, and learn of me; for I am meek and lowly in heart: and ye shall find rest unto your souls. For my yoke is easy, and my burden is light."
      },
      "topics": {
        "christian": "Come and Find Rest"
      }
    },
    "p_23b0f988": {
      "texts": {
        "bsb": "You are the light of the world. A city on a hill cannot be hidden. Neither do people light a lamp and put it under a basket. Instead, they set it on a stand, and it gives light to everyone in the house. In the same way, let your light shine before men, that they may see your good deeds and glorify your Father in heaven.",
        "kjv": "Ye are the light of the world. A city that is set on an hill cannot be hid. Neither do men light a candle, and put it under a bushel, but on a candlestick; and it giveth light unto all that are in the house. Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven."
      },
      "topics": {
        "christian": "You Are the Light"
      }
    },
    "p_ff5987d6": {
      "texts": {
        "bsb": "For God so loved the world that He gave His one and only Son, that everyone who believes in Him shall not perish but have eternal life.",
        "kjv": "¶ For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life."
      },
      "topics": {
        "christian": "God Loves the World"
      }
    },
    "p_a65c43b1": {
      "texts": {
        "bsb": "If you love Me, you will keep My commandments.",
        "kjv": "¶ If ye love me, keep my commandments."
      },
      "topics": {
        "christian": "Love and Obey Jesus"
      }
    }
  },
